for name,file in [('upstream_cad','build_cad.py'),('upstream_definition','build_pluck_product.py')]:sources[name]=ROOT/'source-supplement'/file

def ref(name,function=None):
    p=sources[name];x={'source':name,'path':str(p),'sha256':a.sha(p)}
    if function:
        n=next((n for n in ast.walk(ast.parse(p.read_text())) if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name==function),None)
        if n:x['lines']=[n.lineno,n.end_lineno]
    if name.startswith('upstream_'):
        if name=='upstream_cad':rel='scripts/door_case/build_cad.py'
        elif name=='upstream_definition':rel='scripts/build_pluck_product.py'
        else:rel=str(p.relative_to(a.UP))
        x['url']='https://github.com/littleandbrother/agent/blob/338d60384d5805abf1e02252a4513860066a2c39/battery-world/'+rel
    return x
